from pathlib import Path
import json,math,hashlib
p=Path(__file__).resolve().parent;rs=json.loads((p/'results.json').read_text());eta=1-math.exp(-1.5)
lines=['# 方管DNS验证报告（2026-09-20）','','## 结论','已完成11个DNS工况的测试。径向映射在其预测均速线附近表现较好；这不等于整个断面都达到相同精度。高雷诺数作者数据库3组（文件标称Re_tau=500/1000/2000）的均速线反演误差平均绝对值为0.79%/1.11%/1.10%，最大值4.10%/3.03%/2.37%。这些是不依赖粗糙度的模型检验。','','## 数据及适用范围','- KIT作者原始库：Pinelli等2010研究对应的6组，Re_b=U_b*h/nu约2205、2400、2600、2900、3200、3500，Re_tau约149–225。https://www.iwu.kit.edu/nfm/dns_data/duct/','- 罗马大学作者数据库：5组文件标称Re_tau=150、220、500、1000、2000。http://newton.dma.uniroma1.it/square_duct/ 。这与前述Pirozzoli/Modesti方管研究系列相对应；当前网站是共享更新数据库，文件名是工况标签，不能把每一文件都视为某一篇论文新增的独立试验，也不把2018与2022重复工况计两遍。','- 共11个数值模拟工况，来自2个作者数据库，不是11次现场实验。工况为规则等截面、充分发展、光滑壁面的方管；没有Zhou现场那类障碍物或分汇流。','- KIT原始二进制按作者Matlab脚本的小端int32/float64与Fortran顺序读取。直接采用头部U_b归一化；罗马数据直接采用u/ub列，未用模型输出构造真值。','- 对KIT数据按方管8重对称平均；罗马四分之一断面再按交换两横向坐标平均。目的是比较统计对称平均场，结果不涵盖未对称平均的有限采样不对称性。','- 罗马数据没有墙面与中心边界节点：墙面补无滑移0，中心采用最近节点的对称延拓。全部场使用双线性插值。原文件、来源、SHA256和计算脚本均保存在本目录。','','## A. 不依赖粗糙度的均速线检验','现有模型 phi=1+[ln(1-eta)+1.5]/[ln(r0/epsilon)+1.9]。所以eta*=1-exp(-1.5)=0.77686984时，phi=1且K=1，与epsilon无关。','沿对称八分之一轮廓等间距采样41个方向位置，以DNS点速作输入、DNS独立体积均速作参考，误差=100*(K*u_DNS/U_b-1)。表内平均为41个轮廓采样点的算术平均，不是断面面积平均；这些采样点不是独立试验。','','|来源/工况|均速线MAPE|最大绝对误差|误差≤5%的采样点比例|','|---|---:|---:|---:|']
def label(r):return ('KIT Re_b≈'+str(round(r['Re_b_halfwidth']))) if 'Re_b_halfwidth' in r else 'Rome Re_tau标签='+str(r['Re_tau_filename'])
for r in rs:
 m=r['contour_summary'];lines.append(f"|{label(r)}|{m['mape_pct']:.2f}%|{m['max_abs_pct']:.2f}%|{m['within_5_pct']:.1f}%|")
lines+=['','全部451个轮廓采样点评估均小于10%，其中各工况最大误差见上表；这一结论只适用于该轮廓上的对称平均DNS场。','位置与风速误差不能混淆：高Re的均速线速度误差较小，但实际均速线壁距与模型壁距仍可能有约10%–17%的相对差异，不能据此声称几何轮廓位置误差也是1%。','','## B. 当前默认参数的区域测试（条件性结果）','为避免暗中调参，固定模型几何W=H=4 m、epsilon=0.0055 m，因此epsilon/r0=0.00275；将DNS无量纲横向坐标按h映射到模型。输入u_DNS/U_b，参考均速为1。此处4 m仅为运行现有有量纲接口的代表尺寸，不是论文给出的实体管道尺寸；默认粗糙度也不是光滑DNS的物理粗糙度。','因此下面是既定参数下的数值对照，不是光滑壁面模型经过物理匹配的精度验收。没有利用这些数据拟合epsilon。','用400×400个等面积中点覆盖对称四分之一断面；eta≤0.9对应全断面81%的面积，避开最靠壁区域。同时报告eta≤0.8、0.95和全域中点结果于results.json，未按误差删点。','','|来源/工况|eta≤0.9 MAPE|eta≤0.9 最大绝对误差|全域中点MAPE（含近壁）|','|---|---:|---:|---:|']
for r in rs:
 sub={a['eta_limit']:a for a in r['sensitivity'] if a['epsilon_over_r0']==.00275};a=sub[.9];b=sub[1.];lines.append(f"|{label(r)}|{a['mape_pct']:.2f}%|{a['max_abs_pct']:.2f}%|{b['mape_pct']:.2f}%|")
lines+=['','全域中点靠近无滑移壁面时DNS速度趋近0，而模型仍使用对数近似，因此局部反演误差可以很大。全域中点不包含数学边界，也不意味着更靠壁处模型永远有效。','另做epsilon/r0=1e-5、1e-4、0.001、0.00275、0.01的预设敏感性扫描，结果全部保留，不选最小误差作为主结果。','','## C. 几何映射的独立限制','在同一eta上，现有模型必定给出相同K。但DNS的速度仍随方向改变。以eta=0.9为例，在41个方向样本中记速度比的最小与最大值为a、b，任何共同K的最大反演绝对相对误差至少为(b-a)/(b+a)。这与选用何种一维径向速度函数无关，也不能通过仅调粗糙度消除。','','|来源/工况|同eta最小u/U_b|同eta最大u/U_b|任何共同K的误差下界|','|---|---:|---:|---:|']
for r in rs:
 a=r['rings'][3];lines.append(f"|{label(r)}|{a['min_ratio']:.4f}|{a['max_ratio']:.4f}|{a['unavoidable_max_mean_inversion_error_pct']:.2f}%|")
lines+=['','该下界是这组方向采样的数学诊断，不是整个断面MAPE。低Re时eta=0.9附近可能处于缓冲层，对数速度假设本身也不充分；不可把这些结果全归咎于几何。高Re仍存在方向差异，但在这个eta上的误差下界约3.35%–4.90%。','','## 数值核查与复现','- 每组DNS速度积分核查：积分均速与来源均速之比为'+f"{min(r['integrated_u_over_ub'] for r in rs):.6f}–{max(r['integrated_u_over_ub'] for r in rs):.6f}"+'，最大偏差约0.202%。未重新归一化掩盖差异，结果不适合解释到小数点后三位。','- 200×200与400×400中点网格复核：固定默认参数下各区域MAPE变化最大'+f"{max(abs(a['mape_pct']-b['mape_pct']) for r in rs for a,b in zip([x for x in r['sensitivity'] if x['epsilon_over_r0']==.00275],r['coarse_grid_check'])):.4f}"+'个百分点。该项仅检验本次积分采样，不是原始DNS网格收敛证明。','- 66次真实C++ CLI调用：33次验证均速线K=1，33次核查非均速线点的公式一致性；均通过1e-9精度断言。大规模场计算采用等价公式加速。','- 模型源代码和参数默认值没有修改。结果脚本validate_dns.py、results.json、cli_audit.json、原始文件和归一化npz均可复现。','','## 对模型的评价','目前证据支持：径向映射作为规则方管的工程近似有合理性，特别是高Re均速线附近；但不能说它准确重建了全断面风场。需要改进的是对角区/方向差异的表达，以及速度函数对Re、光滑/粗糙壁和近壁层的适配。半圆拱、三心拱、梯形不能直接继承方管的误差百分数。']
(p/'方管DNS模型验证报告.md').write_text('\n'.join(lines),encoding='utf-8')
print('report written',len(lines))
